<!doctype html><html lang="vi"><head><meta charset="utf-8"><style>@page{margin:24px}body{font-family:"DejaVu Sans",sans-serif;color:#17382a;font-size:11px}.header{text-align:center;border-bottom:2px solid #168451;padding-bottom:12px}.org{font-weight:bold;font-size:13px}.title{font-size:22px;font-weight:bold;margin:14px 0 4px}.meta{color:#577064}.grid{width:100%;margin:18px 0;border-collapse:collapse}.grid td{padding:7px 4px;border-bottom:1px solid #dce8e1}.label{width:34%;color:#60756a}.amount{background:#edf8f1;border:1px solid #b8ddc7;border-radius:6px;padding:12px;text-align:center;font-size:17px;font-weight:bold;color:#0f7044}.sign{width:100%;margin-top:30px;text-align:center}.sign td{width:50%;vertical-align:top}.note{margin-top:24px;color:#687b71;font-size:9px;text-align:center}</style></head><body><div class="header"><div class="org">{{ $settings['Tên đơn vị'] ?? '' }}</div><div>{{ $settings['Địa chỉ'] ?? '' }}</div><div>ĐT: {{ $settings['Số điện thoại'] ?? '' }} - MST: {{ $settings['Mã số thuế'] ?? '' }}</div><div class="title">PHIẾU THU</div><div class="meta">Số: {{ $payment->code }} - Ngày {{ $payment->paid_at->format('d/m/Y') }}</div></div><table class="grid"><tr><td class="label">Hộ dân</td><td><strong>{{ $payment->household->owner_name }}</strong> ({{ $payment->household->code }})</td></tr><tr><td class="label">Địa chỉ</td><td>{{ $payment->household->address }}</td></tr><tr><td class="label">Tuyến thu</td><td>{{ $payment->household->route?->name ?? 'Chưa phân tuyến' }}</td></tr><tr><td class="label">Kỳ thu</td><td>{{ $payment->from_month->format('m/Y') }} - {{ $payment->to_month->format('m/Y') }}</td></tr><tr><td class="label">Hình thức</td><td>{{ $payment->payment_method === 'TIEN_MAT' ? 'Tiền mặt' : 'Chuyển khoản' }}</td></tr><tr><td class="label">Ghi chú</td><td>{{ $payment->note ?: 'Không có' }}</td></tr></table><div class="amount">TỔNG TIỀN: {{ number_format((float)$payment->amount,0,',','.') }} Đ</div><table class="sign"><tr><td><strong>Người nộp tiền</strong><br><small>(Ký, ghi rõ họ tên)</small></td><td><strong>Người thu tiền</strong><br><small>{{ $payment->collector?->name }}</small></td></tr></table><div class="note">Phiếu được tạo từ Hệ thống quản lý phí rác phường An Khê.</div></body></html>
